CREATE TABLE IF NOT EXISTS agent_runtime_execution_materials (
    tenant_id text NOT NULL, reference text NOT NULL, schema_id text NOT NULL, canonical_json text NOT NULL,
    CONSTRAINT execution_materials_pk PRIMARY KEY (tenant_id,reference),
    CONSTRAINT execution_materials_content_ck CHECK (trim(tenant_id)<>'' AND trim(reference)<>'' AND trim(schema_id)<>'' AND trim(canonical_json)<>'')
) STRICT;
